<script setup lang="ts">
import {ref,onMounted} from 'vue';import {get,write} from '../../../../packages/shared/src/client';import {useTask,type Row} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
const task=useTask(),rows=ref<Row[]>([]),selected=ref<Row>(),status=ref('IN_PROGRESS'),reason=ref(''),evidence=ref('');
async function load(){await task.run(async()=>{rows.value=await get('/admin/user/account-privacy/requests');});}
function open(row:Row){selected.value=row;status.value='IN_PROGRESS';reason.value='';evidence.value='';}
async function save(){if(!selected.value)return;const row=selected.value;const saved=await task.run(async()=>{await write('/admin/user/account-privacy/requests/'+row.id,'PUT',{version:row.version,status:status.value,reason:reason.value,evidenceReference:evidence.value||null});selected.value=undefined;return true;});if(saved)await load();}
onMounted(load);
</script>
<template><section class="card"><h1>隐私权利申请</h1><p>显示最多100条待审核申请。账户下载仅含身份资料；完整导出与跨业务删除须核对交易、学习及安全记录的保留规则后处理。完成操作必须留下交付或清理证据，不会自动删除业务历史。</p><Status :busy="task.busy.value" :error="task.error.value"/><el-button :disabled="task.busy.value" @click="load">刷新申请</el-button><el-table :data="rows"><el-table-column prop="id" label="申请编号"/><el-table-column prop="user_id" label="用户编号"/><el-table-column prop="kind" label="申请类型"/><el-table-column prop="status" label="状态"/><el-table-column prop="retained_domains" label="需核对的业务范围"/><el-table-column label="操作"><template #default="scope"><el-button @click="open(scope.row)">核对并处理</el-button></template></el-table-column></el-table><el-dialog :model-value="!!selected" title="处理隐私申请" @update:model-value="(v:boolean)=>{if(!v)selected=undefined;}"><el-select v-model="status"><el-option value="IN_PROGRESS" label="处理中"/><el-option value="COMPLETED" label="已按规则完成"/><el-option value="REJECTED" label="说明原因后拒绝"/></el-select><el-input v-model="reason" type="textarea" maxlength="1000" placeholder="记录处理依据与保留说明"/><el-input v-model="evidence" maxlength="255" placeholder="证据引用（完成时必填；勿填密钥或下载凭据）"/><template #footer><el-button type="primary" :disabled="task.busy.value||!reason.trim()||(status==='COMPLETED'&&!evidence.trim())" @click="save">记录处理结果</el-button></template></el-dialog></section></template>
